import * as React from "react";
import Layout from "../components/layout";
import { graphql, Link, PageProps } from "gatsby";
import  data  from "../data/data.json";
import { UserProfile } from "../interfaces";
import { useTranslation } from "gatsby-plugin-react-i18next";
import EmailForm from "../components/emailForm";
import images from "../images";
import styles from "../styles/pagesStyles";

const userData: UserProfile = data;

const ContactPage: React.FC<PageProps> = () => {
  const { t } = useTranslation();
  return (
    <Layout data={userData}>
      <section className={styles.container}>
      <article className={`${styles.section} !p-0`}>
          <div className="h-96" 
          style={{ 
            backgroundImage: `url(${images.contact_1.src}`, 
            backgroundRepeat: "no-repeat", 
            backgroundSize: "cover", 
            backgroundPosition: "bottom center", 
            borderRadius: "0.5rem" }}></div>
        </article>

      <article className={styles.section}>
          <h2 className={styles.title} dangerouslySetInnerHTML={{ __html: t('contact.block1.title') || '' }} />
          <p className={styles.paragraph} dangerouslySetInnerHTML={{ __html: t('contact.block1.copy') || '' }} />
          <p className={styles.paragraph} dangerouslySetInnerHTML={{ __html: t('contact.block1.copy_2') || '' }} />
          <p className={styles.paragraph} dangerouslySetInnerHTML={{ __html: t('contact.block1.copy_3') || '' }} />
        </article>

        <article className={styles.section}>
          <div className={styles.articleWrapper}>
            <div className="w-full sm:w-1/2 min-h-80">
              <iframe src="https://www.google.com/maps/embed?pb=!1m18!1m12!1m3!1d712130.6567355616!2d-74.48792083750007!3d45.79602813834479!2m3!1f0!2f0!3f0!3m2!1i1024!2i768!4f13.1!3m3!1m2!1s0x4cc94aed72c0da37%3A0xb56fcae9fad35c90!2sPlanchers%20%26%20R%C3%A9novations%20Pierre%20Chevrier!5e0!3m2!1ses!2sca!4v1739760776564!5m2!1ses!2sca" width="100%" height="450"  loading="lazy"></iframe>
            </div>
            <div className="flex flex-col p-4 w-full sm:w-1/2">
              <h2 className={styles.title} dangerouslySetInnerHTML={{ __html: t('contact.block1.copy_4') || '' }} />
              <p className={styles.paragraph} dangerouslySetInnerHTML={{ __html: t('contact.block1.copy_5') || '' }} />
              <EmailForm />
            </div>
          </div>
        </article>

      </section>
    </Layout>
  )
}

export default ContactPage


export const query = graphql`
  query ($language: String!) {
    locales: allLocale(filter: { language: { eq: $language } }) {
      edges {
        node {
          ns
          data
          language
        }
      }
    }
  }
`;